window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-3458a98615fe79f0"]={"versions": [{"id": "FIG-3458a98615fe79f0", "releases": ["R17-03_R1.1.0", "R17-10_R1.2.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm aus der AUTOSAR Adaptive Platform (TPS Manifest Specification). Es definiert die metamodellierte Struktur zur Abbildung einzelner Event-Elemente (<code>ServiceInterfaceEventMapping</code>) im Rahmen des Service-Interface-Mappings.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>ServiceInterfaceMappingSet</code>: Als <code>ARElement</code> typisiertes Wurzelelement/Container.\n</li><li><code>ServiceInterfaceElementMapping</code>: Abstrakte Basisklasse, spezialisiert <code>Identifiable</code>.\n<ul class=\"fig-list\"><li>Gehört über eine Komposition mit der Rollenbezeichnung <code>+elementMapping</code> und Multiplizität <code>0..*</code> zu <code>ServiceInterfaceMappingSet</code>.\n</li></ul>\n</li><li><code>ServiceInterfaceEventMapping</code>: Spezialisiert <code>ServiceInterfaceElementMapping</code> über Generalisierung/Vererbung.\n<ul class=\"fig-list\"><li>Besitzt eine gerichtete Referenz <code>+sourceEvent</code> mit Multiplizität <code>1</code> auf ein <code>VariableDataPrototype</code>.\n</li><li>Besitzt eine gerichtete Referenz <code>+targetEvent</code> mit Multiplizität <code>1</code> auf ein <code>VariableDataPrototype</code>.\n</li></ul>\n</li><li><code>VariableDataPrototype</code>: Datenprototyp, spezialisiert <code>AutosarDataPrototype</code>, dient als Ziel beider Event-Referenzen.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Verhaltens- oder Sequenzdarstellung. Die Instanzen bilden zur Konfigurations- oder Manifest-Erstellungszeit ein konkretes Quell-Event (<code>sourceEvent</code>) paarweise auf ein Ziel-Event (<code>targetEvent</code>) ab.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Klasse <code>ServiceInterfaceEventMapping</code> erfordert zwingend jeweils genau eine Quell- und Ziel-Event-Referenz (<code>1</code>), die beide auf Instanzen von <code>VariableDataPrototype</code> verweisen müssen. Event-Mappings sind aggregiert in einem <code>ServiceInterfaceMappingSet</code> zu führen.</p>"}, {"id": "FIG-cdccb37d9c569808", "releases": ["R18-03_R1.4.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm aus der AUTOSAR Adaptive Platform (TPS Manifest Specification). Es definiert die metamodellierte Struktur zur Abbildung einzelner Event-Elemente (<code>ServiceInterfaceEventMapping</code>) im Rahmen des Service-Interface-Mappings.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>ServiceInterfaceMappingSet</code>: Als <code>ARElement</code> typisiertes Wurzelelement/Container.\n</li><li><code>ServiceInterfaceElementMapping</code>: Abstrakte Basisklasse, spezialisiert <code>Identifiable</code>.\n<ul class=\"fig-list\"><li>Gehört über eine Komposition mit der Rollenbezeichnung <code>+elementMapping</code> und Multiplizität <code>0..*</code> zu <code>ServiceInterfaceMappingSet</code>.\n</li></ul>\n</li><li><code>ServiceInterfaceEventMapping</code>: Spezialisiert <code>ServiceInterfaceElementMapping</code> über Generalisierung/Vererbung.\n<ul class=\"fig-list\"><li>Besitzt eine gerichtete Referenz <code>+sourceEvent</code> mit Multiplizität <code>1</code> auf ein <code>VariableDataPrototype</code>.\n</li><li>Besitzt eine gerichtete Referenz <code>+targetEvent</code> mit Multiplizität <code>1</code> auf ein <code>VariableDataPrototype</code>.\n</li></ul>\n</li><li><code>VariableDataPrototype</code>: Datenprototyp, spezialisiert <code>AutosarDataPrototype</code>, dient als Ziel beider Event-Referenzen.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Verhaltens- oder Sequenzdarstellung. Die Instanzen bilden zur Konfigurations- oder Manifest-Erstellungszeit ein konkretes Quell-Event (<code>sourceEvent</code>) paarweise auf ein Ziel-Event (<code>targetEvent</code>) ab.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Klasse <code>ServiceInterfaceEventMapping</code> erfordert zwingend jeweils genau eine Quell- und Ziel-Event-Referenz (<code>1</code>), die beide auf Instanzen von <code>VariableDataPrototype</code> verweisen müssen. Event-Mappings sind aggregiert in einem <code>ServiceInterfaceMappingSet</code> zu führen.</p>"}, {"id": "FIG-80b31c9b5363b485", "releases": ["R18-10-1", "R18-10_R4.4.0_R1.5.0", "R19-03", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm aus der AUTOSAR Adaptive Platform (TPS Manifest Specification). Es definiert die metamodellierte Struktur zur Abbildung einzelner Event-Elemente (<code>ServiceInterfaceEventMapping</code>) im Rahmen des Service-Interface-Mappings.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>ServiceInterfaceMappingSet</code>: Als <code>ARElement</code> typisiertes Wurzelelement/Container.\n</li><li><code>ServiceInterfaceElementMapping</code>: Abstrakte Basisklasse, spezialisiert <code>Identifiable</code>.\n<ul class=\"fig-list\"><li>Gehört über eine Komposition mit der Rollenbezeichnung <code>+elementMapping</code> und Multiplizität <code>0..*</code> zu <code>ServiceInterfaceMappingSet</code>.\n</li></ul>\n</li><li><code>ServiceInterfaceEventMapping</code>: Spezialisiert <code>ServiceInterfaceElementMapping</code> über Generalisierung/Vererbung.\n<ul class=\"fig-list\"><li>Besitzt eine gerichtete Referenz <code>+sourceEvent</code> mit Multiplizität <code>1</code> auf ein <code>VariableDataPrototype</code>.\n</li><li>Besitzt eine gerichtete Referenz <code>+targetEvent</code> mit Multiplizität <code>1</code> auf ein <code>VariableDataPrototype</code>.\n</li></ul>\n</li><li><code>VariableDataPrototype</code>: Datenprototyp, spezialisiert <code>AutosarDataPrototype</code>, dient als Ziel beider Event-Referenzen.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Verhaltens- oder Sequenzdarstellung. Die Instanzen bilden zur Konfigurations- oder Manifest-Erstellungszeit ein konkretes Quell-Event (<code>sourceEvent</code>) paarweise auf ein Ziel-Event (<code>targetEvent</code>) ab.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Klasse <code>ServiceInterfaceEventMapping</code> erfordert zwingend jeweils genau eine Quell- und Ziel-Event-Referenz (<code>1</code>), die beide auf Instanzen von <code>VariableDataPrototype</code> verweisen müssen. Event-Mappings sind aggregiert in einem <code>ServiceInterfaceMappingSet</code> zu führen.</p>"}, {"id": "FIG-0000f9e1a25dcd74", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm aus der AUTOSAR Adaptive Platform (TPS Manifest Specification). Es definiert die metamodellierte Struktur zur Abbildung einzelner Event-Elemente (<code>ServiceInterfaceEventMapping</code>) im Rahmen des Service-Interface-Mappings.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>ServiceInterfaceMappingSet</code>: Als <code>ARElement</code> typisiertes Wurzelelement/Container.\n</li><li><code>ServiceInterfaceElementMapping</code>: Abstrakte Basisklasse, spezialisiert <code>Identifiable</code>.\n<ul class=\"fig-list\"><li>Gehört über eine Komposition mit der Rollenbezeichnung <code>+elementMapping</code> und Multiplizität <code>0..*</code> zu <code>ServiceInterfaceMappingSet</code>.\n</li></ul>\n</li><li><code>ServiceInterfaceEventMapping</code>: Spezialisiert <code>ServiceInterfaceElementMapping</code> über Generalisierung/Vererbung.\n<ul class=\"fig-list\"><li>Besitzt eine gerichtete Referenz <code>+sourceEvent</code> mit Multiplizität <code>1</code> auf ein <code>VariableDataPrototype</code>.\n</li><li>Besitzt eine gerichtete Referenz <code>+targetEvent</code> mit Multiplizität <code>1</code> auf ein <code>VariableDataPrototype</code>.\n</li></ul>\n</li><li><code>VariableDataPrototype</code>: Datenprototyp, spezialisiert <code>AutosarDataPrototype</code>, dient als Ziel beider Event-Referenzen.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Verhaltens- oder Sequenzdarstellung. Die Instanzen bilden zur Konfigurations- oder Manifest-Erstellungszeit ein konkretes Quell-Event (<code>sourceEvent</code>) paarweise auf ein Ziel-Event (<code>targetEvent</code>) ab.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Klasse <code>ServiceInterfaceEventMapping</code> erfordert zwingend jeweils genau eine Quell- und Ziel-Event-Referenz (<code>1</code>), die beide auf Instanzen von <code>VariableDataPrototype</code> verweisen müssen. Event-Mappings sind aggregiert in einem <code>ServiceInterfaceMappingSet</code> zu führen.</p>"}, {"id": "FIG-53231fe1beab3999", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm aus der AUTOSAR Adaptive Platform (TPS Manifest Specification). Es definiert die metamodellierte Struktur zur direkten Abbildung einzelner Event-Elemente (<code>ServiceInterfaceEventMapping</code>) als eigenständige Modellartefakte.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>ServiceInterfaceElementMapping</code>: Abstrakte Basisklasse, spezialisiert direkt <code>ARElement</code>.\n</li><li><code>ServiceInterfaceEventMapping</code>: Spezialisiert <code>ServiceInterfaceElementMapping</code> über Generalisierung/Vererbung.\n<ul class=\"fig-list\"><li>Besitzt eine gerichtete Referenz <code>+sourceEvent</code> mit Multiplizität <code>1</code> auf ein <code>VariableDataPrototype</code>.\n</li><li>Besitzt eine gerichtete Referenz <code>+targetEvent</code> mit Multiplizität <code>1</code> auf ein <code>VariableDataPrototype</code>.\n</li></ul>\n</li><li><code>VariableDataPrototype</code>: Datenprototyp, spezialisiert <code>AutosarDataPrototype</code>, dient als Ziel der Event-Referenzen.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Verhaltens- oder Sequenzdarstellung. Die Instanzen bilden zur Konfigurations- oder Manifest-Erstellungszeit ein konkretes Quell-Event (<code>sourceEvent</code>) paarweise auf ein Ziel-Event (<code>targetEvent</code>) ab.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\"><code>ServiceInterfaceElementMapping</code> ist nun direkt als <code>ARElement</code> definiert, wodurch Mapping-Definitionen ohne übergeordnetes <code>ServiceInterfaceMappingSet</code> eigenständig im AUTOSAR-Paketbaum instanziiert werden können. Jedes <code>ServiceInterfaceEventMapping</code> muss weiterhin genau ein <code>sourceEvent</code> und genau ein <code>targetEvent</code> referenzieren.</p>"}], "trans": [{"from": "FIG-3458a98615fe79f0", "to": "FIG-cdccb37d9c569808", "fr": "R17-10_R1.2.0", "tr": "R18-03_R1.4.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-cdccb37d9c569808", "to": "FIG-80b31c9b5363b485", "fr": "R18-03_R1.4.0", "tr": "R18-10-1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-80b31c9b5363b485", "to": "FIG-0000f9e1a25dcd74", "fr": "R19-11", "tr": "R20-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Gesamtes Klassendiagramm: Layout von vertikaler Stapelanordnung auf horizontale/zweispaltige Anordnung umgestellt.\n</li><li>Assoziationen <code>+sourceEvent</code> und <code>+targetEvent</code>: Führung der Referenzpfeile verläuft nun horizontal nach rechts statt vertikal nach unten.\n</li><li>Komposition <code>+elementMapping</code>: Verbindung verläuft nun horizontal nach rechts zum Container <code>ServiceInterfaceMappingSet</code> statt vertikal nach oben.\n</li></ul>"}, {"from": "FIG-0000f9e1a25dcd74", "to": "FIG-53231fe1beab3999", "fr": "R20-11", "tr": "R21-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Klasse <code>ServiceInterfaceMappingSet</code>: Entfällt vollständig mitsamt der Kompositionsbeziehung <code>+elementMapping</code> (Kardinalität <code>0..*</code>).\n</li><li>Klasse <code>ServiceInterfaceElementMapping</code>: Stereotyp/Spezialisierung ändert sich von <code>Identifiable</code> zu <code>ARElement</code> (wird damit ein eigenständiges Top-Level-Modellelement).\n</li></ul>"}]};
